package io.knowledgebrain.media;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class MediaApiTest {
 MediaStore store;ObjectStorage storage;SpaceAuthorizationClient authority;MediaController api;UUID space,actor,media;
 @BeforeEach void setup(){store=mock(MediaStore.class);storage=mock(ObjectStorage.class);authority=mock(SpaceAuthorizationClient.class);api=new MediaController(store,storage,authority,new SimpleMeterRegistry(),"https://localhost:8443");var ids=new UuidV7(Clock.systemUTC());space=ids.next();actor=ids.next();media=ids.next();when(authority.authorize(eq(space),eq("a".repeat(43)),anyBoolean(),anyString())).thenReturn(actor);}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("POST","/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");r.setContent("{}".getBytes());return r;}
 @Test void missingOriginDuplicateCookieAndAuthorityFailureNeverReachStorage(){var missing=request();missing.removeHeader("Origin");assertThatThrownBy(()->api.create(space,missing)).isInstanceOf(ResponseStatusException.class);var r=request();r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)),new Cookie("__Host-brain_guest","b".repeat(43)));var duplicate=r;assertThatThrownBy(()->api.create(space,duplicate)).isInstanceOf(ResponseStatusException.class);when(authority.authorize(eq(space),anyString(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE));assertThatThrownBy(()->api.get(space,media,request())).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(store,storage);}
 @Test void commandBodiesAreBoundedAndCompleteIsIdempotent() throws Exception {for(String body:List.of("{} {}","{\"url\":\"https://evil.example\"}","{\"x\":1,\"x\":2}")){var r=request();r.setContent(body.getBytes());assertThatThrownBy(()->api.complete(space,media,r)).isInstanceOf(ResponseStatusException.class);}verifyNoInteractions(store,storage);var done=new MediaStore.Info(media,space,"AVAILABLE",2,"a.pdf","application/pdf",1,"a".repeat(64),Instant.now(),Instant.now());when(store.get(space,media)).thenReturn(done);assertThat(api.complete(space,media,request()).getBody()).isEqualTo(done);verifyNoInteractions(storage);}
}
